// The worker-iac manifests (workers/iac/tools.d) are parsed against REAL
// tool output: the fixtures in testdata/manifests/iac were generated by
// running each manifest's command in the pathos-worker-iac image (KICS
// 2.2.1, KubeLinter 0.8.3, Kubescape 4.0.21, TFLint 0.66.0, Conftest 0.71.1
// with the PATHOS policy bundle, Hadolint 2.15.1, cfn-lint 1.60.1, cfn_nag
// 0.8.10, Polaris 10.2.6, kube-score 1.20.0, Trivy 0.76.2 in config mode,
// OpenSSF Scorecard 5.7.0 in --local mode), offline (docker run --network
// none), on the sample in testdata/manifests/iac/sample mounted at
// /work/fixture/src (the worker's workspace layout), e.g.
//
//	docker run --rm --network none --entrypoint sh \
//	  -v $PWD/testdata/manifests/iac/sample:/work/fixture/src:ro -v /tmp/out:/out pathos-worker-iac:dev \
//	  -c '/opt/pathos/iac/bin/kics-scan /work/fixture/src /out/kics.json /tmp;
//	      /opt/pathos/iac/bin/hadolint-tree /work/fixture/src > /out/hadolint.json; ...'
//
// with the arguments of each manifest. The files are the tools' output
// unchanged.

const iacManifests = "../../../workers/iac/tools.d"

func loadIaCSpec(t *testing.T, file string) PluginDef {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(iacManifests, file))
	if err != nil {
		t.Fatal(err)
	}
	d, err := decodeManifestSpec(raw, true)
	if err != nil {
		t.Fatalf("%s: %v", file, err)
	}
	return d
}

func TestIaCManifestsParseRealOutput(t *testing.T) {
	cases := []struct {
		manifest, fixture, key, category, parser string
		rules                                    []string // rule ids that must be found
		min                                      int
		lines                                    bool // findings have line numbers
		files                                    []string
	}{
		{"kics.yaml", "kics.json", "kics", "iac", "import:kics",
			[]string{"35113e6f-2c6b-414d-beec-7a9482d3b2d1", "dd29336b-fe57-445b-a26e-e6aa867ae609", "67fd0c4a-68cf-46d7-8c41-bc9fba7e40ae",
				"6e856af2-62d7-4ba2-adc1-73b62cef9cc1"}, 20, true,
			[]string{"terraform/main.tf", "k8s/deployment.yaml", "docker/Dockerfile", "cloudformation/template.yaml"}},
		{"kube-linter.yaml", "kube-linter.json", "kube-linter", "iac", "import:kube-linter",
			[]string{"privileged-container", "host-network", "latest-tag", "run-as-non-root"}, 5, false, []string{"k8s/deployment.yaml", "k8s/pod.yaml"}},
		{"kubescape.yaml", "kubescape.json", "kubescape", "iac", "import:kubescape",
			[]string{"C-0057", "C-0041", "C-0013"}, 5, false, []string{"k8s/deployment.yaml"}},
		{"tflint.yaml", "tflint.json", "tflint", "iac", "import:tflint",
			[]string{"terraform_unused_declarations", "terraform_typed_variables"}, 2, true, []string{"terraform/main.tf"}},
		{"conftest.yaml", "conftest.json", "conftest", "iac", "import:conftest",
			[]string{"PATHOS-K8S-001", "PATHOS-K8S-002", "PATHOS-K8S-003", "PATHOS-K8S-004", "PATHOS-K8S-005", "PATHOS-DOCKER-001",
				"PATHOS-DOCKER-003", "PATHOS-DOCKER-004", "PATHOS-TF-001", "PATHOS-TF-002", "PATHOS-TF-003", "PATHOS-TF-004"}, 13, false,
			[]string{"k8s/deployment.yaml", "k8s/pod.yaml", "docker/Dockerfile", "terraform/main.tf"}},
		{"hadolint.yaml", "hadolint.json", "hadolint", "iac", "import:hadolint",
			[]string{"DL3006", "DL3025", "DL3002"}, 4, true, []string{"docker/Dockerfile"}},
		{"cfn-lint.yaml", "cfn-lint.json", "cfn-lint", "iac", "import:cfn-lint",
			[]string{}, 1, true, []string{"cloudformation/template.yaml"}},
		{"cfn-nag.yaml", "cfn-nag.json", "cfn-nag", "iac", "import:cfn-nag",
			[]string{"F1000", "W2"}, 3, true, []string{"cloudformation/template.yaml"}},
		{"polaris.yaml", "polaris.json", "polaris", "iac", "import:polaris",
			[]string{"runAsPrivileged", "hostNetworkSet", "runAsRootAllowed"}, 5, false, nil},
		{"kube-score.yaml", "kube-score.json", "kube-score", "iac", "import:kube-score",
			[]string{"container-security-context-privileged", "container-image-tag", "pod-networkpolicy", "service-type"}, 5, true,
			[]string{"k8s/deployment.yaml", "k8s/pod.yaml"}},
		{"trivy-config.yaml", "trivy-config.sarif", "trivy-config", "iac", "sarif",
			[]string{"KSV-0017", "DS-0002", "AWS-0107"}, 10, true, []string{"k8s/deployment.yaml", "docker/Dockerfile", "terraform/main.tf"}},
		{"scorecard.yaml", "scorecard.json", "scorecard", "supply-chain", "import:scorecard",
			[]string{"Dangerous-Workflow", "Token-Permissions", "Pinned-Dependencies", "Security-Policy"}, 5, false, nil},
	}
	for _, c := range cases {
		t.Run(c.key, func(t *testing.T) {
			d := loadIaCSpec(t, c.manifest)
			if d.Key() != c.key || d.Category != c.category || d.ToolParser().String() != c.parser || !d.FirstParty {
				t.Fatalf("manifest: key %s category %s parser %s", d.Key(), d.Category, d.ToolParser().String())
			}
			if d.Network != "none" || d.Intrusive || !d.RunsOn("") || d.RunsOn("url") || d.RequiresBuild || d.DefaultEnabled {
				t.Errorf("offline repository tool, off by default: %+v", d)
			}
			if d.LicenseSPDX == "" || d.Family != "iac" || len(d.ScanTypes) == 0 || d.Timeout == "" {
				t.Errorf("licence, family, scan types and timeout are declared: %+v", d)
			}
			sc, _ := scanners.Lookup(c.key)
			if !sc.AdapterAvailable || sc.Family != "iac" || sc.License != d.LicenseSPDX || sc.Network != "none" || !scanners.ManifestRouted(c.key) {
				t.Errorf("catalog entry: %+v", sc)
			}
			for _, st := range d.ScanTypes {
				if !slices.Contains(scanners.ScanTypesOf(c.key), st) {
					t.Errorf("scan type %s does not list %s (%v)", st, c.key, scanners.ScanTypesOf(c.key))
				}
			}
			raw, err := os.ReadFile(filepath.Join("testdata", "manifests", "iac", c.fixture))
			if err != nil {
				t.Fatal(err)
			}
			fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
			if err != nil {
				t.Fatalf("parse: %v", err)
			}
			if len(fs) < c.min {
				t.Fatalf("findings: %d, want at least %d", len(fs), c.min)
			}
			var rules, files []string
			fps := map[string]bool{}
			for _, f := range fs {
				rules = append(rules, f.RuleID)
				if !slices.Contains(files, f.FilePath) {
					files = append(files, f.FilePath)
				}
				if f.ScannerKey != c.key || f.Category != c.category || f.Fingerprint == "" || f.Title == "" {
					t.Errorf("finding: %+v", f)
				}
				if strings.HasPrefix(f.FilePath, "/") || strings.Contains(f.FilePath, "work/") || strings.Contains(f.FilePath, "..") {
					t.Errorf("repository-relative path: %q", f.FilePath)
				}
				if c.lines && f.FilePath != "" && (f.StartLine == nil || *f.StartLine <= 0) {
					t.Errorf("line: %+v", f)
				}
				if scanners.SeverityRank(f.Severity) == 0 && f.Severity != "info" {
					t.Errorf("severity %q", f.Severity)
				}
				fps[f.Fingerprint] = true
				// Every finding is found again in the original report.
				loc, err := scanners.LocateToolOutput(d.Key(), d.ToolParser(), raw, f.Fingerprint)
				if err != nil || loc == nil || len(loc.Raw) == 0 {
					t.Errorf("locate %s: %v", f.RuleID, err)
				}
			}
			if len(fps) != len(fs) {
				t.Errorf("fingerprints are distinct: %d of %d", len(fps), len(fs))
			}
			for _, r := range c.rules {
				if !slices.Contains(rules, r) {
					t.Errorf("rule %s not found in %v", r, rules)
				}
			}
			for _, f := range c.files {
				if !slices.Contains(files, f) {
					t.Errorf("file %s not found in %v", f, files)
				}
			}
		})
	}
}

func TestIaCManifestsLoad(t *testing.T) {
	// Every shipped manifest loads as a first-party tool once its command
	// exists (here: a stand-in), and names a catalog tool of the iac family.
	dir := t.TempDir()
	bin := fakeTool(t, dir)
	conf := filepath.Join(dir, "tools.d")
	_ = os.MkdirAll(conf, 0o755)
	entries, _ := os.ReadDir(iacManifests)
	for _, e := range entries {
		raw, _ := os.ReadFile(filepath.Join(iacManifests, e.Name()))
		var cmd string
		for _, l := range strings.Split(string(raw), "\n") {
			if strings.HasPrefix(l, "command: ") {
				cmd = strings.TrimPrefix(l, "command: ")
			}
		}
		_ = os.WriteFile(filepath.Join(conf, e.Name()), []byte(strings.Replace(string(raw), "command: "+cmd, "command: "+bin, 1)), 0o644)
	}
	defs := LoadToolManifests(conf, slog.New(slog.NewTextHandler(io.Discard, nil)))
	var keys []string
	for _, d := range defs {
		keys = append(keys, d.Key())
		if d.Family != "iac" || d.Network != "none" {
			t.Errorf("%s: family %s network %s", d.Key(), d.Family, d.Network)
		}
	}
	want := []string{"cfn-lint", "cfn-nag", "conftest", "hadolint", "kics", "kube-linter", "kube-score", "kubescape", "polaris", "scorecard",
		"tflint", "trivy-config"}
	if !slices.Equal(keys, want) {
		t.Fatalf("first-party manifests: %v, want %v", keys, want)
	}
}

func TestKubeScoreRunsSecurityChecksOnly(t *testing.T) {
	// The kube-score-tree helper ignores kube-score's reliability checks,
	// so every finding of the manifest tool is an iac finding.
	raw, err := os.ReadFile(filepath.Join("testdata", "manifests", "iac", "kube-score.json"))
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range mustParseImport(t, "import-other-x", "kube-score", raw) {
		if f.Category != "iac" {
			t.Errorf("%s: category %s (a reliability check ran)", f.RuleID, f.Category)
		}
	}
}

func mustParseImport(t *testing.T, key, format string, raw []byte) []scanners.Finding {
	t.Helper()
	fs, err := scanners.ParseImport(key, format, raw)
	if err != nil {
		t.Fatal(err)
	}
	return fs
}
